DO $release_guard$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.zasp_schema_versions WHERE version=23 AND name='security_agent_connector_revocation')
     OR EXISTS(SELECT 1 FROM public.zasp_schema_versions WHERE version>23)
     OR NOT EXISTS(SELECT 1 FROM public.zasp_schema_metadata WHERE key='production_core_schema' AND value='security-agent-connector-revocation-v1') THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent session isolation release drift';
  END IF;
END
$release_guard$;

DO $product_release_evolution$
DECLARE definition text;original_definition text;
BEGIN
  SELECT pg_get_functiondef('public.zasp_workflow_mutate(text,text,text,text,text,text,text,text,text,bigint,jsonb,jsonb,text,text,text)'::regprocedure) INTO STRICT definition;
  original_definition:=definition;
  definition:=replace(definition,'security-agent-connector-revocation-v1','security-agent-session-isolation-v1');
  definition:=replace(definition,'release."version" = 23','release."version" = 24');
  definition:=replace(definition,'release."name" = ''security_agent_connector_revocation''','release."name" = ''security_agent_session_isolation''');
  definition:=replace(definition,'later_release."version" > 23','later_release."version" > 24');
  IF definition=original_definition OR position('security-agent-session-isolation-v1' IN definition)=0 OR position('release."version" = 24' IN definition)=0 OR position('security_agent_session_isolation' IN definition)=0 OR position('later_release."version" > 24' IN definition)=0 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='workflow v24 compatibility evolution failed';END IF;
  EXECUTE definition;

  SELECT pg_get_functiondef('public.zasp_risk_mutate(text,text,text,text,text,text,text,bigint,text,text,text,text,text)'::regprocedure) INTO STRICT definition;
  original_definition:=definition;
  definition:=replace(definition,'security-agent-connector-revocation-v1','security-agent-session-isolation-v1');
  definition:=replace(replace(definition,'release."version"=23','release."version"=24'),'release."version" = 23','release."version" = 24');
  definition:=replace(replace(definition,'release."name"=''security_agent_connector_revocation''','release."name"=''security_agent_session_isolation'''),'release."name" = ''security_agent_connector_revocation''','release."name" = ''security_agent_session_isolation''');
  definition:=replace(replace(definition,'later."version">23','later."version">24'),'later."version" > 23','later."version" > 24');
  IF definition=original_definition OR position('security-agent-session-isolation-v1' IN definition)=0 OR position('security_agent_session_isolation' IN definition)=0 OR position('release."version"=24' IN definition)=0 AND position('release."version" = 24' IN definition)=0 OR position('later."version">24' IN definition)=0 AND position('later."version" > 24' IN definition)=0 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='risk v24 compatibility evolution failed';END IF;
  EXECUTE definition;
END
$product_release_evolution$;

DO $restore_helpers$
DECLARE definition text;helper text;
BEGIN
  SELECT pg_get_functiondef('public.zasp_runtime_gateway_record_event(text,text,bigint,bigint,bytea,bigint,text,text,jsonb,timestamptz)'::regprocedure) INTO STRICT definition;
  helper:=replace(definition,'CREATE OR REPLACE FUNCTION public.zasp_runtime_gateway_record_event','CREATE FUNCTION public.zasp_runtime_gateway_record_event_v23_restore');
  IF helper=definition THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='gateway record restore helper rejected';END IF;
  EXECUTE helper;
  ALTER FUNCTION public.zasp_runtime_gateway_record_event_v23_restore(text,text,bigint,bigint,bytea,bigint,text,text,jsonb,timestamptz) OWNER TO zasp_discovery_authority;
  REVOKE ALL ON FUNCTION public.zasp_runtime_gateway_record_event_v23_restore(text,text,bigint,bigint,bytea,bigint,text,text,jsonb,timestamptz) FROM PUBLIC,zasp_gateway_control,zasp_security_agent_api,zasp_security_agent_worker,zasp_security_agent_action_worker;

  SELECT pg_get_functiondef('public.zasp_security_agent_execution_control_detail(text,text,text)'::regprocedure) INTO STRICT definition;
  helper:=replace(definition,'CREATE OR REPLACE FUNCTION public.zasp_security_agent_execution_control_detail','CREATE FUNCTION public.zasp_security_agent_execution_control_detail_v23_restore');
  IF helper=definition THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='execution control restore helper rejected';END IF;
  EXECUTE helper;
  ALTER FUNCTION public.zasp_security_agent_execution_control_detail_v23_restore(text,text,text) OWNER TO zasp_discovery_authority;
  REVOKE ALL ON FUNCTION public.zasp_security_agent_execution_control_detail_v23_restore(text,text,text) FROM PUBLIC,zasp_security_agent_api,zasp_security_agent_worker,zasp_security_agent_action_worker,zasp_gateway_control;

  SELECT pg_get_functiondef('public.zasp_security_agent_mutate_execution_control(text,text,text,text,text,text,text,boolean,bigint,timestamptz,text,text,text)'::regprocedure) INTO STRICT definition;
  helper:=replace(definition,'CREATE OR REPLACE FUNCTION public.zasp_security_agent_mutate_execution_control','CREATE FUNCTION public.zasp_security_agent_mutate_execution_control_v23_restore');
  IF helper=definition THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='execution control mutation restore helper rejected';END IF;
  EXECUTE helper;
  ALTER FUNCTION public.zasp_security_agent_mutate_execution_control_v23_restore(text,text,text,text,text,text,text,boolean,bigint,timestamptz,text,text,text) OWNER TO zasp_discovery_authority;
  REVOKE ALL ON FUNCTION public.zasp_security_agent_mutate_execution_control_v23_restore(text,text,text,text,text,text,text,boolean,bigint,timestamptz,text,text,text) FROM PUBLIC,zasp_security_agent_api,zasp_security_agent_worker,zasp_security_agent_action_worker,zasp_gateway_control;
END
$restore_helpers$;

ALTER TABLE public.zasp_security_agent_temporary_policy_targets DROP CONSTRAINT zasp_security_agent_temporary_policy_targets_action_key_check;
ALTER TABLE public.zasp_security_agent_temporary_policy_targets ADD CONSTRAINT zasp_security_agent_temporary_policy_targets_action_key_check CHECK(action_key IN('create_temporary_policy','isolate_session'));
ALTER TABLE public.zasp_security_agent_definitions ADD CONSTRAINT zasp_security_agent_session_isolation_supervised_check CHECK(NOT (body->'allowed_actions' ? 'isolate_session') OR activation<>'autonomous' AND body->>'autonomy'='supervised');
CREATE INDEX zasp_runtime_gateway_events_session_v24_idx ON public.zasp_runtime_gateway_events(organization_id,workspace_id,environment_id,(classification->>'session_id'),occurred_at DESC,event_id DESC) WHERE classification ? 'session_id';

CREATE OR REPLACE FUNCTION public.zasp_runtime_gateway_record_event(credential_value text,event_value text,expected_floor_value bigint,next_floor_value bigint,request_digest_value bytea,policy_version_value bigint,decision_value text,action_kind_value text,classification_value jsonb,occurred_value timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public AS $record$
DECLARE authority_value jsonb;organization_value text;workspace_value text;environment_value text;device_value text;existing_value zasp_runtime_gateway_events%ROWTYPE;canonical_digest bytea;result_value jsonb;
BEGIN
 IF NOT zasp_valid_product_id(event_value) OR expected_floor_value<0 OR next_floor_value<=expected_floor_value OR octet_length(request_digest_value)<>32 OR policy_version_value<1 OR decision_value NOT IN('allow','monitor','block') OR action_kind_value NOT IN('http','mcp') OR jsonb_typeof(classification_value)<>'object'
  OR NOT classification_value ?& ARRAY['category','route_class','resource_class','outcome'] OR classification_value-ARRAY['category','route_class','resource_class','outcome','session_id','agent_id','target_id','capability_category','capability_outcome']<>'{}'::jsonb
  OR octet_length(convert_to(classification_value::text,'UTF8'))>16384 OR EXISTS(SELECT 1 FROM jsonb_each_text(classification_value) item WHERE length(item.value) NOT BETWEEN 1 AND 128 OR item.value<>btrim(item.value) OR item.value!~'^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$')
  OR classification_value ? 'session_id' AND NOT zasp_valid_product_id(classification_value->>'session_id')
  OR classification_value ?| ARRAY['agent_id','target_id','capability_category','capability_outcome'] AND (decision_value<>'block' OR NOT classification_value ?& ARRAY['agent_id','target_id','capability_category','capability_outcome'] OR NOT zasp_valid_product_id(classification_value->>'agent_id') OR NOT zasp_valid_product_id(classification_value->>'target_id') OR (classification_value->>'capability_category',classification_value->>'capability_outcome') NOT IN(('data_read','read'),('data_write','write'),('action_execute','execute'),('identity_assume','assume'),('network_egress','connect'),('administration','administer')))
  OR occurred_value IS NULL OR occurred_value>transaction_timestamp()+interval '30 seconds' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='gateway event rejected';END IF;
 authority_value:=zasp_runtime_gateway_credential_authority(credential_value,'runtime-gateway');organization_value:=authority_value->>'organization_id';workspace_value:=authority_value->>'workspace_id';environment_value:=authority_value->>'environment_id';device_value:=authority_value->>'device_id';
 canonical_digest:=digest(convert_to(jsonb_build_object('credential_id',credential_value,'device_id',device_value,'event_id',event_value,'expected_floor',expected_floor_value,'next_floor',next_floor_value,'policy_version',policy_version_value,'decision',decision_value,'action_kind',action_kind_value,'classification',classification_value,'occurred_at',to_char(occurred_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::text,'UTF8'),'sha256');
 IF canonical_digest<>request_digest_value THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='gateway event rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,device_value),0));
 SELECT * INTO existing_value FROM zasp_runtime_gateway_events event_row WHERE (event_row.organization_id,event_row.workspace_id,event_row.environment_id,event_row.event_id)=(organization_value,workspace_value,environment_value,event_value);
 IF FOUND THEN
  IF (existing_value.device_id,existing_value.credential_id,existing_value.sequence,existing_value.request_digest,existing_value.policy_version,existing_value.decision,existing_value.action_kind,existing_value.classification,existing_value.occurred_at) IS DISTINCT FROM (device_value,credential_value,next_floor_value,request_digest_value,policy_version_value,decision_value,action_kind_value,classification_value,occurred_value) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='gateway event rejected';END IF;
  UPDATE zasp_runtime_gateway_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;RETURN jsonb_build_object('event_id',event_value,'device_id',device_value,'sequence',next_floor_value,'recorded_at',existing_value.recorded_at,'replayed',true);
 END IF;
 IF occurred_value<transaction_timestamp()-interval '24 hours' THEN UPDATE zasp_runtime_gateway_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;RETURN jsonb_build_object('event_id',event_value,'outcome','record_window_expired');END IF;
 IF classification_value ? 'agent_id' THEN PERFORM zasp_inventory_record_capability_evidence(organization_value,workspace_value,environment_value,classification_value->>'agent_id',classification_value->>'target_id',classification_value->>'capability_category',classification_value->>'capability_outcome','runtime_policy',event_value,occurred_value);END IF;
 PERFORM zasp_runtime_gateway_advance_replay(credential_value,expected_floor_value,next_floor_value,request_digest_value);
 INSERT INTO zasp_runtime_gateway_events(organization_id,workspace_id,environment_id,device_id,credential_id,event_id,sequence,request_digest,policy_version,decision,action_kind,classification,occurred_at) VALUES(organization_value,workspace_value,environment_value,device_value,credential_value,event_value,next_floor_value,request_digest_value,policy_version_value,decision_value,action_kind_value,classification_value,occurred_value) RETURNING jsonb_build_object('event_id',event_id,'device_id',device_id,'sequence',sequence,'recorded_at',recorded_at,'replayed',false) INTO result_value;
 UPDATE zasp_runtime_gateway_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;RETURN result_value;
END
$record$;

CREATE OR REPLACE FUNCTION public.zasp_security_agent_execution_control_detail(organization_value text,workspace_value text,environment_value text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO pg_catalog, public AS $detail$
DECLARE global_row zasp_security_agent_kill_switches%ROWTYPE;environment_row zasp_security_agent_kill_switches%ROWTYPE;temporary_row zasp_security_agent_kill_switches%ROWTYPE;isolate_row zasp_security_agent_kill_switches%ROWTYPE;revoke_row zasp_security_agent_kill_switches%ROWTYPE;finding_row zasp_security_agent_kill_switches%ROWTYPE;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent execution control detail rejected';END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_environments environment WHERE (environment.organization_id,environment.workspace_id,environment.id)=(organization_value,workspace_value,environment_value)) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='security agent execution control scope not found';END IF;
  SELECT * INTO STRICT global_row FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=('*','*','*','*');
  SELECT * INTO environment_row FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=(organization_value,workspace_value,environment_value,'*');
  SELECT * INTO temporary_row FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=(organization_value,workspace_value,environment_value,'create_temporary_policy');
  SELECT * INTO isolate_row FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=(organization_value,workspace_value,environment_value,'isolate_session');
  SELECT * INTO revoke_row FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=(organization_value,workspace_value,environment_value,'revoke_integration_connection');
  SELECT * INTO finding_row FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=(organization_value,workspace_value,environment_value,'update_finding_response');
  RETURN jsonb_build_object('global',jsonb_build_object('target','global','action_key','*','enabled',global_row.execution_enabled,'version',global_row.version),'environment',jsonb_build_object('target','environment','action_key','*','enabled',COALESCE(environment_row.execution_enabled,false),'version',COALESCE(environment_row.version,0)),'actions',jsonb_build_array(jsonb_build_object('target','action','action_key','create_temporary_policy','enabled',COALESCE(temporary_row.execution_enabled,false),'version',COALESCE(temporary_row.version,0)),jsonb_build_object('target','action','action_key','isolate_session','enabled',COALESCE(isolate_row.execution_enabled,false),'version',COALESCE(isolate_row.version,0)),jsonb_build_object('target','action','action_key','revoke_integration_connection','enabled',COALESCE(revoke_row.execution_enabled,false),'version',COALESCE(revoke_row.version,0)),jsonb_build_object('target','action','action_key','update_finding_response','enabled',COALESCE(finding_row.execution_enabled,false),'version',COALESCE(finding_row.version,0))));
END
$detail$;

CREATE OR REPLACE FUNCTION public.zasp_security_agent_mutate_execution_control(organization_value text,workspace_value text,environment_value text,actor_value text,idempotency_value text,target_value text,action_value text,enabled_value boolean,expected_version bigint,fresh_auth_expires_value timestamptz,audit_value text,correlation_value text,receipt_value text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public AS $mutate$
DECLARE row_organization text;row_workspace text;row_environment text;row_action text;intent_value jsonb;intent_digest_value bytea;receipt_row zasp_security_agent_request_receipts%ROWTYPE;result_value jsonb;response_value jsonb;resource_value text;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(actor_value) OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) OR NOT zasp_valid_product_id(receipt_value) OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR idempotency_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' OR target_value NOT IN('environment','action') OR expected_version<0 OR fresh_auth_expires_value IS NULL OR fresh_auth_expires_value<=transaction_timestamp() OR fresh_auth_expires_value>transaction_timestamp()+interval '5 minutes 5 seconds' OR (target_value='action' AND action_value NOT IN('create_temporary_policy','isolate_session','revoke_integration_connection','update_finding_response')) OR (target_value<>'action' AND action_value<>'*') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent execution control mutation rejected';END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_environments environment WHERE (environment.organization_id,environment.workspace_id,environment.id)=(organization_value,workspace_value,environment_value)) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='security agent execution control scope not found';END IF;
  IF target_value='environment' THEN row_organization:=organization_value;row_workspace:=workspace_value;row_environment:=environment_value;row_action:='*';ELSE row_organization:=organization_value;row_workspace:=workspace_value;row_environment:=environment_value;row_action:=action_value;END IF;
  resource_value:=target_value||':'||row_action;intent_value:=jsonb_build_object('target',target_value,'action_key',row_action,'enabled',enabled_value,'expected_version',expected_version);intent_digest_value:=digest(convert_to(intent_value::text,'UTF8'),'sha256');
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,actor_value,'setSecurityAgentExecutionControl',idempotency_value),0));
  SELECT * INTO receipt_row FROM zasp_security_agent_request_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.principal_id,receipt.operation,receipt.idempotency_key)=(organization_value,workspace_value,environment_value,actor_value,'setSecurityAgentExecutionControl',idempotency_value);
  IF FOUND THEN
    IF receipt_row.resource_id<>resource_value OR receipt_row.expected_version<>expected_version OR receipt_row.intent_digest<>intent_digest_value OR receipt_row.expires_at<=transaction_timestamp() OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches switch_row WHERE (switch_row.organization_id,switch_row.workspace_id,switch_row.environment_id,switch_row.action_key,switch_row.execution_enabled,switch_row.version)=(row_organization,row_workspace,row_environment,row_action,enabled_value,(receipt_row.response->>'version')::bigint)) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='security agent execution control replay conflict';END IF;
    RETURN receipt_row.response||jsonb_build_object('replayed',true);
  END IF;
  IF enabled_value AND NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent global execution disabled';END IF;
  IF enabled_value AND target_value='action' AND NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true)) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent environment execution disabled';END IF;
  result_value:=zasp_security_agent_set_kill_switch(row_organization,row_workspace,row_environment,row_action,enabled_value,expected_version,actor_value,audit_value,correlation_value);
  response_value:=result_value||jsonb_build_object('target',target_value,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',false);
  INSERT INTO zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id) VALUES(organization_value,workspace_value,environment_value,actor_value,'setSecurityAgentExecutionControl',idempotency_value,resource_value,expected_version,intent_value,intent_digest_value,response_value,audit_value,correlation_value,receipt_value);
  RETURN response_value;
END
$mutate$;

CREATE FUNCTION public.zasp_security_agent_schedule_session_isolation_triggers(worker_value text,limit_value integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public AS $schedule$
DECLARE candidate record;trigger_digest_value bytea;run_value text;audit_value text;correlation_value text;created_value integer:=0;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_worker') OR length(worker_value) NOT BETWEEN 1 AND 128 OR limit_value NOT BETWEEN 1 AND 25 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session isolation scheduling rejected';END IF;
  FOR candidate IN
    WITH violations AS (
      SELECT definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version definition_version,(definition.body->>'concurrency_limit')::integer concurrency_limit,
             event.classification->>'session_id' session_id,event.device_id,max(event.sequence) trigger_version,max(event.occurred_at) occurred_at,count(*) violation_count
      FROM zasp_security_agent_definitions definition
      JOIN zasp_runtime_gateway_events event ON (event.organization_id,event.workspace_id,event.environment_id)=(definition.organization_id,definition.workspace_id,definition.environment_id)
      JOIN zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,'active')
      JOIN zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id,credential.id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,event.credential_id)
      WHERE definition.activation='supervised' AND definition.deleted_at IS NULL AND definition.body->>'enabled'='true' AND definition.body->>'trigger_kind'='runtime_decision' AND definition.body->'environment_ids' ? definition.environment_id
        AND definition.body->'allowed_actions'=jsonb_build_array('isolate_session') AND definition.body->>'verification_kind'='gateway_decision'
        AND event.decision='block' AND event.classification ? 'session_id' AND zasp_valid_product_id(event.classification->>'session_id') AND event.classification->>'outcome'=definition.body->>'trigger_source' AND event.occurred_at>=transaction_timestamp()-interval '5 minutes'
        AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp()
        AND credential.id=(SELECT current_credential.id FROM zasp_gateway_credentials current_credential WHERE (current_credential.organization_id,current_credential.workspace_id,current_credential.environment_id,current_credential.device_id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id) AND current_credential.revoked_at IS NULL AND current_credential.expires_at>transaction_timestamp() ORDER BY current_credential.issued_at DESC,current_credential.id DESC LIMIT 1)
        AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true))
        AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(definition.organization_id,definition.workspace_id,definition.environment_id,'*',true))
        AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(definition.organization_id,definition.workspace_id,definition.environment_id,'isolate_session',true))
        AND (SELECT count(*) FROM zasp_security_agent_runs running WHERE (running.organization_id,running.workspace_id,running.environment_id,running.definition_id)=(definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id) AND running.state IN('queued','planning','waiting_approval','running','verifying','contained'))<(definition.body->>'concurrency_limit')::integer
      GROUP BY definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version,(definition.body->>'concurrency_limit')::integer,event.classification->>'session_id',event.device_id
      HAVING count(*)>=3
    ), eligible AS (
      SELECT violations.*,row_number() OVER(PARTITION BY organization_id,workspace_id,environment_id,definition_id ORDER BY occurred_at,session_id,device_id) definition_ordinal
      FROM violations
      WHERE NOT EXISTS(SELECT 1 FROM zasp_security_agent_trigger_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.definition_id,receipt.trigger_id,receipt.trigger_version)=(violations.organization_id,violations.workspace_id,violations.environment_id,violations.definition_id,violations.session_id,violations.trigger_version))
    ) SELECT * FROM eligible WHERE definition_ordinal=1 ORDER BY occurred_at,organization_id,workspace_id,environment_id,definition_id LIMIT limit_value
  LOOP
    SELECT digest(convert_to(jsonb_build_object('kind','runtime_decision','session_id',candidate.session_id,'device_id',candidate.device_id,'events',COALESCE(jsonb_agg(jsonb_build_object('event_id',event_id,'sequence',sequence,'request_digest','sha256:'||encode(request_digest,'hex')) ORDER BY sequence,event_id),'[]'::jsonb))::text,'UTF8'),'sha256') INTO trigger_digest_value
    FROM (SELECT event.event_id,event.sequence,event.request_digest FROM zasp_runtime_gateway_events event WHERE (event.organization_id,event.workspace_id,event.environment_id,event.device_id,event.classification->>'session_id')=(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.device_id,candidate.session_id) AND event.decision='block' AND event.sequence<=candidate.trigger_version ORDER BY event.sequence DESC,event.event_id DESC LIMIT 3) recent;
    run_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_run',candidate.definition_id||chr(31)||candidate.session_id||chr(31)||candidate.trigger_version);
    audit_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_audit',run_value||chr(31)||'queued');
    correlation_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_correlation',run_value||chr(31)||'queued');
    INSERT INTO zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,candidate.session_id,'runtime_decision',candidate.trigger_version,trigger_digest_value,run_value) ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN CONTINUE;END IF;
    INSERT INTO zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,run_value,candidate.definition_id,candidate.definition_version,candidate.session_id,worker_value,'queued');
    INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body) VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,audit_value,correlation_value,run_value,worker_value,'run_queued',trigger_digest_value,jsonb_build_object('run_id',run_value,'definition_id',candidate.definition_id,'definition_version',candidate.definition_version,'trigger_kind','runtime_decision','trigger_id',candidate.session_id,'trigger_version',candidate.trigger_version,'device_id',candidate.device_id,'count',candidate.violation_count));
    created_value:=created_value+1;
  END LOOP;
  RETURN jsonb_build_object('created',created_value);
END
$schedule$;

CREATE FUNCTION public.zasp_security_agent_schedule_triggers_v24(worker_value text,limit_value integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public AS $schedule_all$
DECLARE session_count integer;prior_count integer;session_limit integer;
BEGIN
  IF limit_value NOT BETWEEN 1 AND 25 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent scheduling rejected';END IF;
  session_limit:=greatest(1,(limit_value+1)/2);
  session_count:=(zasp_security_agent_schedule_session_isolation_triggers(worker_value,session_limit)->>'created')::integer;
  prior_count:=0;
  IF session_count<limit_value THEN prior_count:=(zasp_security_agent_schedule_triggers_v23(worker_value,limit_value-session_count)->>'created')::integer;END IF;
  RETURN jsonb_build_object('created',session_count+prior_count);
END
$schedule_all$;

CREATE FUNCTION public.zasp_security_agent_run_v24(organization_value text,workspace_value text,environment_value text,definition_value text,actor_value text,idempotency_value text,expected_version bigint,run_value text,trigger_kind_value text,trigger_value text,audit_value text,correlation_value text,receipt_value text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public AS $run$
DECLARE definition_row zasp_security_agent_definitions%ROWTYPE;event_row zasp_runtime_gateway_events%ROWTYPE;trigger_digest_value bytea;intent_value jsonb;intent_digest_value bytea;receipt_row zasp_security_agent_request_receipts%ROWTYPE;prior_run text;prior_state text;prior_version bigint;response_value jsonb;
BEGIN
  IF trigger_kind_value='finding' THEN RETURN zasp_security_agent_run(organization_value,workspace_value,environment_value,definition_value,actor_value,idempotency_value,expected_version,run_value,trigger_kind_value,trigger_value,audit_value,correlation_value,receipt_value);END IF;
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR expected_version<=0 OR trigger_kind_value<>'session' OR NOT zasp_valid_product_id(definition_value) OR NOT zasp_valid_product_id(actor_value) OR NOT zasp_valid_product_id(run_value) OR NOT zasp_valid_product_id(trigger_value) OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) OR NOT zasp_valid_product_id(receipt_value) OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR idempotency_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent run rejected';END IF;
  intent_value:=jsonb_build_object('definition_id',definition_value,'expected_version',expected_version,'trigger_kind',trigger_kind_value,'trigger_id',trigger_value);intent_digest_value:=digest(convert_to(intent_value::text,'UTF8'),'sha256');
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,actor_value,'runSecurityAgent',idempotency_value),0));
  SELECT * INTO receipt_row FROM zasp_security_agent_request_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.principal_id,receipt.operation,receipt.idempotency_key)=(organization_value,workspace_value,environment_value,actor_value,'runSecurityAgent',idempotency_value);
  IF FOUND THEN
    IF receipt_row.resource_id<>definition_value OR receipt_row.expected_version<>expected_version OR receipt_row.intent_digest<>intent_digest_value OR receipt_row.expires_at<=transaction_timestamp() OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_definitions definition WHERE (definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version)=(organization_value,workspace_value,environment_value,definition_value,expected_version) AND definition.deleted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM zasp_runtime_gateway_events event WHERE (event.organization_id,event.workspace_id,event.environment_id,event.classification->>'session_id')=(organization_value,workspace_value,environment_value,trigger_value)) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='security agent run replay conflict';END IF;
    RETURN receipt_row.response||jsonb_build_object('replayed',true);
  END IF;
  SELECT * INTO definition_row FROM zasp_security_agent_definitions definition WHERE (definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version)=(organization_value,workspace_value,environment_value,definition_value,expected_version) AND definition.deleted_at IS NULL AND definition.activation='supervised' AND definition.body->'environment_ids' ? environment_value AND definition.body->>'trigger_kind'='runtime_decision' AND definition.body->>'autonomy'='supervised' AND definition.body->'allowed_actions'=jsonb_build_array('isolate_session') AND definition.body->>'verification_kind'='gateway_decision' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent run definition rejected';END IF;
  SELECT event.* INTO event_row FROM zasp_runtime_gateway_events event JOIN zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,'active') JOIN zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id,credential.id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,event.credential_id) WHERE (event.organization_id,event.workspace_id,event.environment_id,event.classification->>'session_id')=(organization_value,workspace_value,environment_value,trigger_value) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() AND credential.id=(SELECT current_credential.id FROM zasp_gateway_credentials current_credential WHERE (current_credential.organization_id,current_credential.workspace_id,current_credential.environment_id,current_credential.device_id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id) AND current_credential.revoked_at IS NULL AND current_credential.expires_at>transaction_timestamp() ORDER BY current_credential.issued_at DESC,current_credential.id DESC LIMIT 1) ORDER BY event.sequence DESC,event.event_id DESC LIMIT 1 FOR SHARE OF device,credential;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent run trigger denied';END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'isolate_session',true)) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent execution disabled';END IF;
  trigger_digest_value:=digest(convert_to(jsonb_build_object('kind','runtime_decision','session_id',trigger_value,'device_id',event_row.device_id,'event_id',event_row.event_id,'sequence',event_row.sequence,'request_digest','sha256:'||encode(event_row.request_digest,'hex'))::text,'UTF8'),'sha256');
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,definition_value,trigger_value,event_row.sequence),0));
  SELECT receipt.run_id INTO prior_run FROM zasp_security_agent_trigger_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.definition_id,receipt.trigger_id,receipt.trigger_version)=(organization_value,workspace_value,environment_value,definition_value,trigger_value,event_row.sequence);
  IF FOUND THEN
    SELECT state,version INTO STRICT prior_state,prior_version FROM zasp_security_agent_runs existing WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.run_id)=(organization_value,workspace_value,environment_value,prior_run);
    response_value:=jsonb_build_object('id',prior_run,'agent_id',definition_value,'state',prior_state,'evidence_ids',jsonb_build_array(trigger_value),'definition_version',expected_version,'version',prior_version,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',true);
  ELSE
    INSERT INTO zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(organization_value,workspace_value,environment_value,definition_value,trigger_value,'runtime_decision',event_row.sequence,trigger_digest_value,run_value);
    INSERT INTO zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(organization_value,workspace_value,environment_value,run_value,definition_value,expected_version,trigger_value,actor_value,'queued');
    response_value:=jsonb_build_object('id',run_value,'agent_id',definition_value,'state','queued','evidence_ids',jsonb_build_array(trigger_value),'definition_version',expected_version,'version',1,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',false);
  END IF;
  INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body) VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,response_value->>'id',actor_value,CASE WHEN prior_run IS NULL THEN 'run_queued' ELSE 'run_deduplicated' END,trigger_digest_value,jsonb_build_object('run_id',response_value->>'id','definition_id',definition_value,'definition_version',expected_version,'trigger_kind','runtime_decision','trigger_id',trigger_value,'trigger_version',event_row.sequence,'device_id',event_row.device_id));
  INSERT INTO zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id) VALUES(organization_value,workspace_value,environment_value,actor_value,'runSecurityAgent',idempotency_value,definition_value,expected_version,intent_value,intent_digest_value,response_value,audit_value,correlation_value,receipt_value);
  UPDATE zasp_security_agent_execution_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;RETURN response_value;
END
$run$;

CREATE FUNCTION public.zasp_security_agent_prepare_session_isolation_run(organization_value text,workspace_value text,environment_value text,run_value text,worker_value text,lease_token_value text,approval_value text,approval_expires_value timestamptz,audit_value text,correlation_value text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public AS $prepare$
DECLARE run_row zasp_security_agent_runs%ROWTYPE;definition_row zasp_security_agent_definitions%ROWTYPE;trigger_row zasp_security_agent_trigger_receipts%ROWTYPE;event_row zasp_runtime_gateway_events%ROWTYPE;step_value text;plan_value jsonb;plan_digest bytea;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_worker') OR NOT zasp_valid_product_id(run_value) OR NOT zasp_valid_product_id(approval_value) OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) OR length(worker_value) NOT BETWEEN 1 AND 128 OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR approval_expires_value<=transaction_timestamp() OR approval_expires_value>transaction_timestamp()+interval '16 minutes' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session isolation plan rejected';END IF;
  SELECT * INTO run_row FROM zasp_security_agent_runs run WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id,run.state,run.lease_owner,run.lease_token)=(organization_value,workspace_value,environment_value,run_value,'planning',worker_value,lease_token_value) AND run.lease_expires_at>transaction_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent lease lost';END IF;
  SELECT * INTO STRICT definition_row FROM zasp_security_agent_definitions definition WHERE (definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version)=(organization_value,workspace_value,environment_value,run_row.definition_id,run_row.definition_version) AND definition.activation='supervised' AND definition.deleted_at IS NULL AND definition.body->'allowed_actions'=jsonb_build_array('isolate_session') AND definition.body->>'verification_kind'='gateway_decision' AND (definition.body->>'temporary_policy_seconds')::integer BETWEEN 60 AND 3600 FOR SHARE;
  SELECT * INTO STRICT trigger_row FROM zasp_security_agent_trigger_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.run_id,receipt.trigger_kind)=(organization_value,workspace_value,environment_value,run_value,'runtime_decision');
  SELECT event.* INTO event_row FROM zasp_runtime_gateway_events event JOIN zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,'active') JOIN zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id,credential.id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,event.credential_id) WHERE (event.organization_id,event.workspace_id,event.environment_id,event.classification->>'session_id',event.sequence)=(organization_value,workspace_value,environment_value,trigger_row.trigger_id,trigger_row.trigger_version) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() AND credential.id=(SELECT current_credential.id FROM zasp_gateway_credentials current_credential WHERE (current_credential.organization_id,current_credential.workspace_id,current_credential.environment_id,current_credential.device_id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id) AND current_credential.revoked_at IS NULL AND current_credential.expires_at>transaction_timestamp() ORDER BY current_credential.issued_at DESC,current_credential.id DESC LIMIT 1) FOR SHARE OF device,credential;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent session changed';END IF;
  step_value:=zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'security_agent_step',run_value||chr(31)||'0');
  plan_value:=jsonb_build_object('definition_id',run_row.definition_id,'definition_version',run_row.definition_version,'catalog_version','security-agent-actions-v1','evidence_ids',jsonb_build_array(trigger_row.trigger_id),'steps',jsonb_build_array(jsonb_build_object('index',0,'step_id',step_value,'action','isolate_session','target_id',trigger_row.trigger_id,'session_id',trigger_row.trigger_id,'device_id',event_row.device_id,'scope',environment_value,'ttl_seconds',(definition_row.body->>'temporary_policy_seconds')::integer,'authorization','approval_required')),'verification',jsonb_build_object('kind','gateway_decision','expected_state','blocked'),'expires_at',to_char(approval_expires_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
  plan_digest:=digest(convert_to(plan_value::text,'UTF8'),'sha256');
  INSERT INTO zasp_security_agent_plans(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_digest,catalog_version,plan,plan_hash,expires_at) VALUES(organization_value,workspace_value,environment_value,run_value,run_row.definition_id,run_row.definition_version,trigger_row.trigger_digest,'security-agent-actions-v1',plan_value,plan_digest,approval_expires_value);
  INSERT INTO zasp_security_agent_steps(organization_id,workspace_id,environment_id,run_id,step_id,step_index,action_key,input_digest,authorization_result,state) VALUES(organization_value,workspace_value,environment_value,run_value,step_value,0,'isolate_session',digest(convert_to((plan_value->'steps'->0)::text,'UTF8'),'sha256'),'approval_required','waiting_approval');
  INSERT INTO zasp_security_agent_approvals(organization_id,workspace_id,environment_id,approval_id,run_id,step_id,plan_hash,state,requester_id,expires_at) VALUES(organization_value,workspace_value,environment_value,approval_value,run_value,step_value,plan_digest,'pending',run_row.requested_by,approval_expires_value);
  UPDATE zasp_security_agent_runs run SET state='waiting_approval',plan_hash=plan_digest,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=run.version+1,updated_at=transaction_timestamp() WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=(organization_value,workspace_value,environment_value,run_value);
  INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,approval_id,actor_id,event_kind,event_digest,body) VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,run_value,step_value,approval_value,worker_value,'approval_requested',plan_digest,jsonb_build_object('run_id',run_value,'step_id',step_value,'action','isolate_session','session_id',trigger_row.trigger_id,'device_id',event_row.device_id,'approval_id',approval_value,'plan_hash','sha256:'||encode(plan_digest,'hex')));
  RETURN jsonb_build_object('run_id',run_value,'state','waiting_approval','version',run_row.version+1,'approval_id',approval_value,'step_id',step_value,'plan_hash','sha256:'||encode(plan_digest,'hex'));
END
$prepare$;

CREATE FUNCTION public.zasp_security_agent_prepare_run_v24(organization_value text,workspace_value text,environment_value text,run_value text,worker_value text,lease_token_value text,approval_value text,approval_expires_value timestamptz,audit_value text,correlation_value text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public AS $prepare_all$
DECLARE action_value text;
BEGIN
  SELECT definition.body->'allowed_actions'->>0 INTO action_value FROM zasp_security_agent_runs run JOIN zasp_security_agent_definitions definition ON (definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version)=(run.organization_id,run.workspace_id,run.environment_id,run.definition_id,run.definition_version) WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=(organization_value,workspace_value,environment_value,run_value);
  IF action_value='isolate_session' THEN RETURN zasp_security_agent_prepare_session_isolation_run(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value,approval_value,approval_expires_value,audit_value,correlation_value);END IF;
  RETURN zasp_security_agent_prepare_run_v23(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value,approval_value,approval_expires_value,audit_value,correlation_value);
END
$prepare_all$;

CREATE FUNCTION public.zasp_security_agent_dispatch_session_isolation_run(organization_value text,workspace_value text,environment_value text,run_value text,worker_value text,lease_token_value text,audit_value text,correlation_value text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public AS $dispatch$
DECLARE run_row zasp_security_agent_runs%ROWTYPE;trigger_row zasp_security_agent_trigger_receipts%ROWTYPE;plan_row zasp_security_agent_plans%ROWTYPE;step_row zasp_security_agent_steps%ROWTYPE;event_row zasp_runtime_gateway_events%ROWTYPE;outcome_value text;result_digest_value bytea;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_worker') OR NOT zasp_valid_product_id(run_value) OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) OR length(worker_value) NOT BETWEEN 1 AND 128 OR length(lease_token_value) NOT BETWEEN 16 AND 128 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session isolation dispatch rejected';END IF;
  SELECT * INTO run_row FROM zasp_security_agent_runs run WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id,run.state,run.lease_owner,run.lease_token)=(organization_value,workspace_value,environment_value,run_value,'planning',worker_value,lease_token_value) AND run.lease_expires_at>transaction_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent lease lost';END IF;
  SELECT * INTO STRICT trigger_row FROM zasp_security_agent_trigger_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.run_id,receipt.trigger_kind)=(organization_value,workspace_value,environment_value,run_value,'runtime_decision');
  SELECT * INTO STRICT plan_row FROM zasp_security_agent_plans plan WHERE (plan.organization_id,plan.workspace_id,plan.environment_id,plan.run_id,plan.plan_hash)=(organization_value,workspace_value,environment_value,run_value,run_row.plan_hash) AND plan.expires_at>transaction_timestamp() FOR SHARE;
  SELECT * INTO STRICT step_row FROM zasp_security_agent_steps step WHERE (step.organization_id,step.workspace_id,step.environment_id,step.run_id,step.action_key,step.state,step.authorization_result)=(organization_value,workspace_value,environment_value,run_value,'isolate_session','authorized','approval_required') FOR UPDATE;
  PERFORM 1 FROM zasp_security_agent_approvals approval WHERE (approval.organization_id,approval.workspace_id,approval.environment_id,approval.run_id,approval.step_id,approval.state,approval.plan_hash)=(organization_value,workspace_value,environment_value,run_value,step_row.step_id,'approved',run_row.plan_hash) AND approval.expires_at>transaction_timestamp() FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session isolation approval missing';END IF;
  SELECT event.* INTO event_row FROM zasp_runtime_gateway_events event JOIN zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,'active') JOIN zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id,credential.id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,event.credential_id) WHERE (event.organization_id,event.workspace_id,event.environment_id,event.classification->>'session_id',event.sequence,event.device_id)=(organization_value,workspace_value,environment_value,trigger_row.trigger_id,trigger_row.trigger_version,plan_row.plan->'steps'->0->>'device_id') AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() AND credential.id=(SELECT current_credential.id FROM zasp_gateway_credentials current_credential WHERE (current_credential.organization_id,current_credential.workspace_id,current_credential.environment_id,current_credential.device_id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id) AND current_credential.revoked_at IS NULL AND current_credential.expires_at>transaction_timestamp() ORDER BY current_credential.issued_at DESC,current_credential.id DESC LIMIT 1) FOR SHARE OF device,credential;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent session changed';END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_security_agent_definitions definition WHERE (definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version,definition.activation)=(organization_value,workspace_value,environment_value,run_row.definition_id,run_row.definition_version,'supervised') AND definition.deleted_at IS NULL AND definition.body->'allowed_actions'=jsonb_build_array('isolate_session') AND definition.body->>'verification_kind'='gateway_decision') OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'isolate_session',true)) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent execution disabled';END IF;
  INSERT INTO zasp_security_agent_effects(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state) VALUES(organization_value,workspace_value,environment_value,run_value,step_row.step_id,'isolate_session',step_row.input_digest,'pending');
  UPDATE zasp_security_agent_steps step SET state='executing',version=step.version+1,updated_at=transaction_timestamp() WHERE (step.organization_id,step.workspace_id,step.environment_id,step.run_id,step.step_id)=(organization_value,workspace_value,environment_value,run_value,step_row.step_id);
  UPDATE zasp_security_agent_runs run SET state='running',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=run.version+1,updated_at=transaction_timestamp() WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=(organization_value,workspace_value,environment_value,run_value);
  outcome_value:=zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'security_agent_effect',run_value||chr(31)||step_row.step_id||chr(31)||'isolate_session');result_digest_value:=digest(convert_to(jsonb_build_object('run_id',run_value,'step_id',step_row.step_id,'action','isolate_session','session_id',trigger_row.trigger_id,'device_id',event_row.device_id,'state','pending')::text,'UTF8'),'sha256');
  INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,run_value,step_row.step_id,worker_value,'effect_dispatched',result_digest_value,jsonb_build_object('run_id',run_value,'step_id',step_row.step_id,'action','isolate_session','session_id',trigger_row.trigger_id,'device_id',event_row.device_id,'outcome_id',outcome_value));
  RETURN jsonb_build_object('run_id',run_value,'state','running','version',run_row.version+1,'step_id',step_row.step_id,'effect_state','pending','outcome_id',outcome_value,'result_digest','sha256:'||encode(result_digest_value,'hex'));
END
$dispatch$;

CREATE FUNCTION public.zasp_security_agent_execute_run_v24(organization_value text,workspace_value text,environment_value text,run_value text,worker_value text,lease_token_value text,audit_value text,correlation_value text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public AS $execute_all$
DECLARE action_value text;
BEGIN
  SELECT step.action_key INTO action_value FROM zasp_security_agent_steps step WHERE (step.organization_id,step.workspace_id,step.environment_id,step.run_id)=(organization_value,workspace_value,environment_value,run_value);
  IF action_value='isolate_session' THEN RETURN zasp_security_agent_dispatch_session_isolation_run(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value,audit_value,correlation_value);END IF;
  RETURN zasp_security_agent_execute_run_v23(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value,audit_value,correlation_value);
END
$execute_all$;

CREATE FUNCTION public.zasp_security_agent_claim_session_policy_effects(worker_value text,lease_token_value text,lease_seconds integer,claim_limit integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public AS $claim$
DECLARE item record;device_row record;target_row record;items jsonb:='[]'::jsonb;targets jsonb;phase_value text;ttl_seconds integer;sequence_value bigint;policy_version_value bigint;session_value text;target_device_value text;no_target_result bytea;no_target_outcome text;no_target_audit text;no_target_correlation text;
BEGIN
  IF NOT zasp_security_agent_action_principal_ready() OR length(worker_value) NOT BETWEEN 1 AND 128 OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_seconds NOT BETWEEN 30 AND 300 OR claim_limit NOT BETWEEN 1 AND 25 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session policy claim rejected';END IF;
  UPDATE zasp_security_agent_effects effect SET state=CASE WHEN EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key,target.phase,target.state)=(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key,'apply','verified')) THEN 'cleanup_pending' ELSE 'pending' END,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp()
  WHERE effect.action_key IN('create_temporary_policy','isolate_session') AND effect.state='leased' AND effect.lease_expires_at<=transaction_timestamp();
  FOR item IN SELECT effect.* FROM zasp_security_agent_effects effect WHERE effect.action_key IN('create_temporary_policy','isolate_session') AND effect.state='cleanup_pending' AND effect.updated_at<=transaction_timestamp()
    AND NOT EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets applied JOIN zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(applied.organization_id,applied.workspace_id,applied.environment_id,applied.device_id,'active') JOIN zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(device.organization_id,device.workspace_id,device.environment_id,device.id) WHERE (applied.organization_id,applied.workspace_id,applied.environment_id,applied.run_id,applied.step_id,applied.action_key,applied.phase,applied.state)=(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key,'apply','verified') AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp())
    ORDER BY effect.updated_at,effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id LIMIT claim_limit FOR UPDATE SKIP LOCKED
  LOOP
    no_target_result:=digest(item.input_digest,'sha256');no_target_outcome:=zasp_discovery_canonical_id(item.organization_id,item.workspace_id,item.environment_id,'security_agent_effect',item.run_id||chr(31)||item.step_id||chr(31)||'cleanup');no_target_audit:=zasp_discovery_canonical_id(item.organization_id,item.workspace_id,item.environment_id,'security_agent_audit',item.run_id||chr(31)||item.step_id||chr(31)||'cleanup-no-active-target');no_target_correlation:=zasp_discovery_canonical_id(item.organization_id,item.workspace_id,item.environment_id,'security_agent_correlation',item.run_id||chr(31)||item.step_id||chr(31)||'cleanup-no-active-target');
    UPDATE zasp_security_agent_effects effect SET state='cleaned',outcome_id=no_target_outcome,result_digest=no_target_result,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=effect.version+1,updated_at=transaction_timestamp() WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key,effect.state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,item.action_key,'cleanup_pending');
    UPDATE zasp_security_agent_runs run SET state='remediated',version=run.version+1,updated_at=transaction_timestamp(),completed_at=transaction_timestamp() WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id,run.state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,'contained');
    INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(item.organization_id,item.workspace_id,item.environment_id,no_target_audit,no_target_correlation,item.run_id,item.step_id,worker_value,'effect_cleaned',no_target_result,jsonb_build_object('run_id',item.run_id,'step_id',item.step_id,'action',item.action_key,'phase','cleanup','outcome_id',no_target_outcome,'result_digest','sha256:'||encode(no_target_result,'hex'),'reason','no_active_gateway_target')) ON CONFLICT DO NOTHING;
  END LOOP;
  FOR item IN
    WITH selected AS (
      SELECT effect.ctid,effect.state prior_state FROM zasp_security_agent_effects effect
      WHERE effect.action_key IN('create_temporary_policy','isolate_session') AND (effect.state='pending' OR effect.state='cleanup_pending' AND effect.updated_at<=transaction_timestamp())
        AND (effect.state='cleanup_pending' OR EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(effect.organization_id,effect.workspace_id,effect.environment_id,'*',true)) AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(effect.organization_id,effect.workspace_id,effect.environment_id,effect.action_key,true)))
        AND EXISTS(SELECT 1 FROM zasp_gateway_devices device JOIN zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(device.organization_id,device.workspace_id,device.environment_id,device.id) JOIN zasp_security_agent_plans plan ON (plan.organization_id,plan.workspace_id,plan.environment_id,plan.run_id)=(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id) WHERE (device.organization_id,device.workspace_id,device.environment_id,device.state)=(effect.organization_id,effect.workspace_id,effect.environment_id,'active') AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() AND (effect.action_key='create_temporary_policy' OR device.id=plan.plan->'steps'->0->>'device_id'))
      ORDER BY effect.updated_at,effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id LIMIT claim_limit FOR UPDATE SKIP LOCKED
    ), claimed AS (
      UPDATE zasp_security_agent_effects effect SET state='leased',lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),attempt=effect.attempt+1,version=effect.version+1,updated_at=transaction_timestamp() FROM selected WHERE effect.ctid=selected.ctid RETURNING effect.*,selected.prior_state
    ) SELECT * FROM claimed
  LOOP
    phase_value:=CASE item.prior_state WHEN 'cleanup_pending' THEN 'cleanup' ELSE 'apply' END;
    SELECT COALESCE((plan.plan->'steps'->0->>'ttl_seconds')::integer,300),CASE item.action_key WHEN 'isolate_session' THEN plan.plan->'steps'->0->>'session_id' ELSE NULL END,CASE item.action_key WHEN 'isolate_session' THEN plan.plan->'steps'->0->>'device_id' ELSE NULL END INTO ttl_seconds,session_value,target_device_value FROM zasp_security_agent_plans plan WHERE (plan.organization_id,plan.workspace_id,plan.environment_id,plan.run_id)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id);
    IF ttl_seconds NOT BETWEEN 60 AND 3600 OR item.action_key='isolate_session' AND (NOT zasp_valid_product_id(session_value) OR NOT zasp_valid_product_id(target_device_value)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session policy plan rejected';END IF;
    FOR device_row IN SELECT device.id device_id,credential.id credential_id FROM zasp_gateway_devices device JOIN LATERAL (SELECT credential.id FROM zasp_gateway_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(device.organization_id,device.workspace_id,device.environment_id,device.id) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() ORDER BY credential.issued_at DESC,credential.id DESC LIMIT 1) credential ON true WHERE (device.organization_id,device.workspace_id,device.environment_id,device.state)=(item.organization_id,item.workspace_id,item.environment_id,'active') AND (item.action_key='create_temporary_policy' OR device.id=target_device_value) AND (phase_value='apply' OR EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets applied WHERE (applied.organization_id,applied.workspace_id,applied.environment_id,applied.run_id,applied.step_id,applied.action_key,applied.phase,applied.device_id,applied.state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,item.action_key,'apply',device.id,'verified'))) ORDER BY device.id
    LOOP
      PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),item.organization_id,item.workspace_id,item.environment_id,device_row.device_id,'temporary-policy-sequence'),0));
      SELECT COALESCE(max(bundle.sequence)+1,1),COALESCE(max(bundle.policy_version)+1,1) INTO sequence_value,policy_version_value FROM zasp_runtime_gateway_policy_bundles bundle WHERE (bundle.organization_id,bundle.workspace_id,bundle.environment_id,bundle.device_id)=(item.organization_id,item.workspace_id,item.environment_id,device_row.device_id);
      INSERT INTO zasp_security_agent_temporary_policy_targets(organization_id,workspace_id,environment_id,run_id,step_id,action_key,phase,device_id,credential_id,sequence,policy_version) VALUES(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,item.action_key,phase_value,device_row.device_id,device_row.credential_id,sequence_value,policy_version_value)
      ON CONFLICT(organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id) DO UPDATE SET action_key=excluded.action_key,credential_id=excluded.credential_id,sequence=excluded.sequence,policy_version=excluded.policy_version,state='planned',key_id=NULL,issued_at=NULL,expires_at=NULL,failure_mode=NULL,payload_digest=NULL,policies=NULL,signature=NULL,envelope_digest=NULL,stored_at=NULL,verified_at=NULL WHERE zasp_security_agent_temporary_policy_targets.state='planned' OR zasp_security_agent_temporary_policy_targets.credential_id<>excluded.credential_id;
    END LOOP;
    targets:='[]'::jsonb;
    FOR target_row IN SELECT * FROM zasp_security_agent_temporary_policy_targets value WHERE (value.organization_id,value.workspace_id,value.environment_id,value.run_id,value.step_id,value.action_key,value.phase)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,item.action_key,phase_value) ORDER BY value.device_id LOOP targets:=targets||jsonb_build_array(jsonb_build_object('device_id',target_row.device_id,'credential_id',target_row.credential_id,'sequence',target_row.sequence,'policy_version',target_row.policy_version));END LOOP;
    items:=items||jsonb_build_array(jsonb_build_object('organization_id',item.organization_id,'workspace_id',item.workspace_id,'environment_id',item.environment_id,'run_id',item.run_id,'step_id',item.step_id,'action_key',item.action_key,'session_id',session_value,'phase',phase_value,'input_digest','sha256:'||encode(item.input_digest,'hex'),'ttl_seconds',ttl_seconds,'lease_expires_at',to_char(item.lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'targets',targets));
  END LOOP;
  RETURN jsonb_build_object('items',items);
END
$claim$;

CREATE FUNCTION public.zasp_security_agent_heartbeat_session_policy_effect(organization_value text,workspace_value text,environment_value text,run_value text,step_value text,worker_value text,lease_token_value text,lease_seconds integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public AS $heartbeat$
DECLARE expires_value timestamptz;
BEGIN
  IF NOT zasp_security_agent_action_principal_ready() OR lease_seconds NOT BETWEEN 30 AND 300 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session policy heartbeat rejected';END IF;
  UPDATE zasp_security_agent_effects effect SET lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),updated_at=transaction_timestamp() WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.state,effect.lease_owner,effect.lease_token)=(organization_value,workspace_value,environment_value,run_value,step_value,'leased',worker_value,lease_token_value) AND effect.action_key IN('create_temporary_policy','isolate_session') AND effect.lease_expires_at>transaction_timestamp() RETURNING effect.lease_expires_at INTO expires_value;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session policy lease lost';END IF;RETURN jsonb_build_object('lease_expires_at',to_char(expires_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END
$heartbeat$;

CREATE FUNCTION public.zasp_security_agent_store_session_policy_target(organization_value text,workspace_value text,environment_value text,run_value text,step_value text,phase_value text,worker_value text,lease_token_value text,device_value text,credential_value text,sequence_value bigint,policy_version_value bigint,key_value text,issued_value timestamptz,expires_value timestamptz,failure_mode_value text,payload_digest_value bytea,policies_value jsonb,signature_value bytea,envelope_digest_value bytea) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public AS $store$
DECLARE target_row zasp_security_agent_temporary_policy_targets%ROWTYPE;ttl_seconds integer;session_value text;
BEGIN
  IF NOT zasp_security_agent_action_principal_ready() OR phase_value NOT IN('apply','cleanup') OR octet_length(payload_digest_value)<>32 OR octet_length(signature_value)<>64 OR octet_length(envelope_digest_value)<>32 OR jsonb_typeof(policies_value)<>'array' OR jsonb_array_length(policies_value)>100 OR phase_value='cleanup' AND policies_value<>'[]'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session policy target rejected';END IF;
  SELECT * INTO target_row FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id,target.credential_id,target.sequence,target.policy_version)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value,credential_value,sequence_value,policy_version_value) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='session policy target missing';END IF;
  PERFORM 1 FROM zasp_security_agent_effects effect WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key,effect.state,effect.lease_owner,effect.lease_token)=(organization_value,workspace_value,environment_value,run_value,step_value,target_row.action_key,'leased',worker_value,lease_token_value) AND effect.lease_expires_at>transaction_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session policy lease lost';END IF;
  SELECT (plan.plan->'steps'->0->>'ttl_seconds')::integer,plan.plan->'steps'->0->>'session_id' INTO STRICT ttl_seconds,session_value FROM zasp_security_agent_plans plan WHERE (plan.organization_id,plan.workspace_id,plan.environment_id,plan.run_id)=(organization_value,workspace_value,environment_value,run_value);
  IF ttl_seconds NOT BETWEEN 60 AND 3600 OR failure_mode_value<>'closed' OR phase_value='apply' AND expires_value<>issued_value+make_interval(secs=>ttl_seconds) OR phase_value='cleanup' AND expires_value<>issued_value+interval '5 minutes' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session policy target rejected';END IF;
  IF target_row.action_key='isolate_session' AND phase_value='apply' AND (NOT zasp_valid_product_id(session_value) OR jsonb_array_length(policies_value)<>2 OR EXISTS(SELECT 1 FROM jsonb_array_elements(policies_value) policy WHERE policy->>'action'<>'block' OR NOT policy->'conditions' @> jsonb_build_array(jsonb_build_object('field','session_id','operator','equals','value',session_value)))) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session isolation policy rejected';END IF;
  IF phase_value='apply' AND (NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,target_row.action_key,true))) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session policy execution disabled';END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_gateway_devices device WHERE (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(organization_value,workspace_value,environment_value,device_value,'active')) OR credential_value IS DISTINCT FROM (SELECT credential.id FROM zasp_gateway_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(organization_value,workspace_value,environment_value,device_value) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() ORDER BY credential.issued_at DESC,credential.id DESC LIMIT 1) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session policy credential changed';END IF;
  IF target_row.state<>'planned' THEN
    IF (target_row.key_id,target_row.issued_at,target_row.expires_at,target_row.failure_mode,target_row.payload_digest,target_row.policies,target_row.signature,target_row.envelope_digest) IS DISTINCT FROM (key_value,issued_value,expires_value,failure_mode_value,payload_digest_value,policies_value,signature_value,envelope_digest_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='session policy target replay conflict';END IF;
  ELSE
    INSERT INTO zasp_runtime_gateway_policy_bundles(organization_id,workspace_id,environment_id,device_id,credential_id,sequence,policy_version,key_id,algorithm,audience,issued_at,expires_at,failure_mode,payload_digest,policies,signature,envelope_digest) VALUES(organization_value,workspace_value,environment_value,device_value,credential_value,sequence_value,policy_version_value,key_value,'Ed25519','runtime-gateway-policy',issued_value,expires_value,failure_mode_value,payload_digest_value,policies_value,signature_value,envelope_digest_value) ON CONFLICT(organization_id,workspace_id,environment_id,device_id,sequence) DO NOTHING;
    IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM zasp_runtime_gateway_policy_bundles bundle WHERE (bundle.organization_id,bundle.workspace_id,bundle.environment_id,bundle.device_id,bundle.credential_id,bundle.sequence,bundle.policy_version,bundle.key_id,bundle.issued_at,bundle.expires_at,bundle.failure_mode,bundle.payload_digest,bundle.policies,bundle.signature,bundle.envelope_digest)=(organization_value,workspace_value,environment_value,device_value,credential_value,sequence_value,policy_version_value,key_value,issued_value,expires_value,failure_mode_value,payload_digest_value,policies_value,signature_value,envelope_digest_value)) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='session policy bundle conflict';END IF;
    UPDATE zasp_security_agent_temporary_policy_targets target SET state='stored',key_id=key_value,issued_at=issued_value,expires_at=expires_value,failure_mode=failure_mode_value,payload_digest=payload_digest_value,policies=policies_value,signature=signature_value,envelope_digest=envelope_digest_value,stored_at=transaction_timestamp() WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value);
  END IF;
  RETURN jsonb_build_object('device_id',device_value,'phase',phase_value,'sequence',sequence_value,'policy_version',policy_version_value,'envelope_digest','sha256:'||encode(envelope_digest_value,'hex'));
END
$store$;

CREATE FUNCTION public.zasp_security_agent_read_session_policy_target(organization_value text,workspace_value text,environment_value text,run_value text,step_value text,phase_value text,device_value text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO pg_catalog, public AS $read$
DECLARE result_value jsonb;
BEGIN
  IF NOT zasp_security_agent_action_principal_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='session policy target denied';END IF;
  SELECT jsonb_build_object('device_id',target.device_id,'credential_id',target.credential_id,'phase',target.phase,'state',target.state,'sequence',target.sequence,'policy_version',target.policy_version,'key_id',target.key_id,'issued_at',to_char(target.issued_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'expires_at',to_char(target.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'failure_mode',target.failure_mode,'payload_digest','sha256:'||encode(target.payload_digest,'hex'),'policies',target.policies,'signature',encode(target.signature,'base64'),'envelope_digest','sha256:'||encode(target.envelope_digest,'hex')) INTO result_value FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value) AND target.action_key IN('create_temporary_policy','isolate_session') AND target.state IN('stored','verified');
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='session policy target missing';END IF;RETURN result_value;
END
$read$;

CREATE FUNCTION public.zasp_security_agent_finish_session_policy_effect(organization_value text,workspace_value text,environment_value text,run_value text,step_value text,phase_value text,worker_value text,lease_token_value text,result_digest_value bytea,audit_value text,correlation_value text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public AS $finish$
DECLARE effect_row zasp_security_agent_effects%ROWTYPE;outcome_value text;expires_value timestamptz;expected_digest bytea;
BEGIN
  IF NOT zasp_security_agent_action_principal_ready() OR phase_value NOT IN('apply','cleanup') OR octet_length(result_digest_value)<>32 OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session policy finish rejected';END IF;
  SELECT * INTO effect_row FROM zasp_security_agent_effects effect WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.state,effect.lease_owner,effect.lease_token)=(organization_value,workspace_value,environment_value,run_value,step_value,'leased',worker_value,lease_token_value) AND effect.action_key IN('create_temporary_policy','isolate_session') AND effect.lease_expires_at>transaction_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session policy lease lost';END IF;
  IF phase_value='apply' AND (NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,effect_row.action_key,true))) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session policy execution disabled';END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key,phase_value)) OR EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key,phase_value) AND target.state<>'stored') THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session policy verification incomplete';END IF;
  IF EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key,phase_value) AND (NOT EXISTS(SELECT 1 FROM zasp_gateway_devices device WHERE (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(target.organization_id,target.workspace_id,target.environment_id,target.device_id,'active')) OR target.credential_id IS DISTINCT FROM (SELECT credential.id FROM zasp_gateway_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(target.organization_id,target.workspace_id,target.environment_id,target.device_id) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() ORDER BY credential.issued_at DESC,credential.id DESC LIMIT 1))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session policy credential changed';END IF;
  SELECT digest(effect_row.input_digest||decode(string_agg(encode(target.envelope_digest,'hex'),'' ORDER BY target.device_id),'hex'),'sha256') INTO STRICT expected_digest FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key,target.phase,target.state)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key,phase_value,'stored');
  IF expected_digest IS DISTINCT FROM result_digest_value THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session policy result rejected';END IF;
  UPDATE zasp_security_agent_temporary_policy_targets target SET state='verified',verified_at=transaction_timestamp() WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key,phase_value);
  outcome_value:=zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'security_agent_effect',run_value||chr(31)||step_value||chr(31)||phase_value);
  IF phase_value='apply' THEN
    SELECT max(target.expires_at) INTO STRICT expires_value FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key,'apply');
    UPDATE zasp_security_agent_effects effect SET state='cleanup_pending',outcome_id=outcome_value,result_digest=result_digest_value,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=effect.version+1,updated_at=expires_value WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key);
    UPDATE zasp_security_agent_steps step SET state='succeeded',version=step.version+1,updated_at=transaction_timestamp() WHERE (step.organization_id,step.workspace_id,step.environment_id,step.run_id,step.step_id)=(organization_value,workspace_value,environment_value,run_value,step_value);
    UPDATE zasp_security_agent_runs run SET state='contained',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=run.version+1,updated_at=transaction_timestamp() WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=(organization_value,workspace_value,environment_value,run_value);
  ELSE
    UPDATE zasp_security_agent_effects effect SET state='cleaned',outcome_id=outcome_value,result_digest=result_digest_value,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=effect.version+1,updated_at=transaction_timestamp() WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key);
    UPDATE zasp_security_agent_runs run SET state='remediated',version=run.version+1,updated_at=transaction_timestamp(),completed_at=transaction_timestamp() WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=(organization_value,workspace_value,environment_value,run_value);
  END IF;
  INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,run_value,step_value,worker_value,CASE phase_value WHEN 'apply' THEN 'effect_verified' ELSE 'effect_cleaned' END,result_digest_value,jsonb_build_object('run_id',run_value,'step_id',step_value,'action',effect_row.action_key,'phase',phase_value,'outcome_id',outcome_value,'result_digest','sha256:'||encode(result_digest_value,'hex')));
  RETURN jsonb_build_object('run_id',run_value,'step_id',step_value,'phase',phase_value,'effect_state',CASE phase_value WHEN 'apply' THEN 'cleanup_pending' ELSE 'cleaned' END,'outcome_id',outcome_value,'result_digest','sha256:'||encode(result_digest_value,'hex'));
END
$finish$;

CREATE FUNCTION public.zasp_security_agent_approval_value_v24(organization_value text,workspace_value text,environment_value text,approval_value text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO pg_catalog, public AS $approval_value$
DECLARE step_action text;run_row zasp_security_agent_runs%ROWTYPE;approval_row zasp_security_agent_approvals%ROWTYPE;plan_row zasp_security_agent_plans%ROWTYPE;ttl_seconds_value integer;
BEGIN
  SELECT step.action_key INTO STRICT step_action FROM zasp_security_agent_approvals approval JOIN zasp_security_agent_steps step ON (step.organization_id,step.workspace_id,step.environment_id,step.run_id,step.step_id)=(approval.organization_id,approval.workspace_id,approval.environment_id,approval.run_id,approval.step_id) WHERE (approval.organization_id,approval.workspace_id,approval.environment_id,approval.approval_id)=(organization_value,workspace_value,environment_value,approval_value);
  IF step_action<>'isolate_session' THEN RETURN zasp_security_agent_approval_value_v23(organization_value,workspace_value,environment_value,approval_value);END IF;
  SELECT * INTO STRICT approval_row FROM zasp_security_agent_approvals approval WHERE (approval.organization_id,approval.workspace_id,approval.environment_id,approval.approval_id)=(organization_value,workspace_value,environment_value,approval_value);
  SELECT * INTO STRICT run_row FROM zasp_security_agent_runs run WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=(organization_value,workspace_value,environment_value,approval_row.run_id);
  SELECT * INTO STRICT plan_row FROM zasp_security_agent_plans plan WHERE (plan.organization_id,plan.workspace_id,plan.environment_id,plan.run_id,plan.plan_hash)=(organization_value,workspace_value,environment_value,approval_row.run_id,approval_row.plan_hash);
  SELECT (item->>'ttl_seconds')::integer INTO STRICT ttl_seconds_value FROM jsonb_array_elements(plan_row.plan->'steps') item WHERE item->>'step_id'=approval_row.step_id AND item->>'action'='isolate_session';
  IF ttl_seconds_value NOT BETWEEN 60 AND 3600 OR NOT zasp_valid_product_id(plan_row.plan->'steps'->0->>'session_id') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent session approval rejected';END IF;
  RETURN jsonb_build_object('id',approval_row.approval_id,'run_id',approval_row.run_id,'step_id',approval_row.step_id,'state',approval_row.state,'expires_at',to_char(approval_row.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'version',approval_row.version,'expected_effect','Isolate runtime session','reversible',true,'ttl_seconds',ttl_seconds_value,'evidence_summary',jsonb_build_array(run_row.trigger_id));
END
$approval_value$;

CREATE FUNCTION public.zasp_security_agent_run_detail_v24(organization_value text,workspace_value text,environment_value text,run_value text) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO pg_catalog, public AS $detail$ SELECT value||jsonb_build_object('approvals',COALESCE((SELECT jsonb_agg(zasp_security_agent_approval_value_v24(approval.organization_id,approval.workspace_id,approval.environment_id,approval.approval_id) ORDER BY approval.created_at,approval.approval_id) FROM zasp_security_agent_approvals approval WHERE (approval.organization_id,approval.workspace_id,approval.environment_id,approval.run_id)=(organization_value,workspace_value,environment_value,run_value)),'[]'::jsonb)) FROM zasp_security_agent_run_detail(organization_value,workspace_value,environment_value,run_value) detail(value) $detail$;
CREATE FUNCTION public.zasp_security_agent_approval_page_v24(organization_value text,workspace_value text,environment_value text,state_value text,run_value text,before_created_value timestamptz,before_id_value text,limit_value integer) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO pg_catalog, public AS $page$ DECLARE page_value jsonb;items_value jsonb;BEGIN page_value:=zasp_security_agent_approval_page(organization_value,workspace_value,environment_value,state_value,run_value,before_created_value,before_id_value,limit_value);SELECT COALESCE(jsonb_agg(zasp_security_agent_approval_value_v24(organization_value,workspace_value,environment_value,item.value->>'id') ORDER BY item.ordinality),'[]'::jsonb) INTO items_value FROM jsonb_array_elements(page_value->'items') WITH ORDINALITY item(value,ordinality);RETURN jsonb_set(page_value,'{items}',items_value,false);END $page$;
CREATE FUNCTION public.zasp_security_agent_approval_detail_v24(organization_value text,workspace_value text,environment_value text,approval_value text) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO pg_catalog, public AS $detail$ SELECT zasp_security_agent_approval_value_v24(organization_value,workspace_value,environment_value,approval_value) WHERE EXISTS(SELECT 1 FROM zasp_security_agent_approval_detail(organization_value,workspace_value,environment_value,approval_value)) $detail$;
CREATE FUNCTION public.zasp_security_agent_decide_approval_v24(organization_value text,workspace_value text,environment_value text,approval_value text,actor_value text,idempotency_value text,expected_version bigint,decision_value text,fresh_auth_value timestamptz,audit_value text,correlation_value text,receipt_value text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog, public AS $decide$
DECLARE response_value jsonb;
BEGIN
  response_value:=zasp_security_agent_decide_approval(organization_value,workspace_value,environment_value,approval_value,actor_value,idempotency_value,expected_version,decision_value,fresh_auth_value,audit_value,correlation_value,receipt_value);
  RETURN response_value||zasp_security_agent_approval_value_v24(organization_value,workspace_value,environment_value,approval_value);
END
$decide$;

DO $functions$
DECLARE procedure_oid oid;
BEGIN
  FOR procedure_oid IN SELECT procedure.oid FROM pg_proc procedure JOIN pg_namespace namespace ON namespace.oid=procedure.pronamespace WHERE namespace.nspname='public' AND procedure.proname=ANY(ARRAY['zasp_security_agent_schedule_session_isolation_triggers','zasp_security_agent_schedule_triggers_v24','zasp_security_agent_run_v24','zasp_security_agent_prepare_session_isolation_run','zasp_security_agent_prepare_run_v24','zasp_security_agent_dispatch_session_isolation_run','zasp_security_agent_execute_run_v24','zasp_security_agent_claim_session_policy_effects','zasp_security_agent_heartbeat_session_policy_effect','zasp_security_agent_store_session_policy_target','zasp_security_agent_read_session_policy_target','zasp_security_agent_finish_session_policy_effect','zasp_security_agent_approval_value_v24','zasp_security_agent_run_detail_v24','zasp_security_agent_approval_page_v24','zasp_security_agent_approval_detail_v24','zasp_security_agent_decide_approval_v24']) LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO zasp_discovery_authority',procedure_oid::regprocedure);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,zasp_security_agent_api,zasp_security_agent_worker,zasp_security_agent_action_worker,zasp_gateway_control,zasp_discovery_api,zasp_discovery_worker',procedure_oid::regprocedure);
  END LOOP;
END
$functions$;
ALTER FUNCTION public.zasp_runtime_gateway_record_event(text,text,bigint,bigint,bytea,bigint,text,text,jsonb,timestamptz) OWNER TO zasp_discovery_authority;
ALTER FUNCTION public.zasp_security_agent_execution_control_detail(text,text,text) OWNER TO zasp_discovery_authority;
ALTER FUNCTION public.zasp_security_agent_mutate_execution_control(text,text,text,text,text,text,text,boolean,bigint,timestamptz,text,text,text) OWNER TO zasp_discovery_authority;
REVOKE ALL ON FUNCTION public.zasp_runtime_gateway_record_event(text,text,bigint,bigint,bytea,bigint,text,text,jsonb,timestamptz) FROM PUBLIC,zasp_security_agent_api,zasp_security_agent_worker,zasp_security_agent_action_worker;
GRANT EXECUTE ON FUNCTION public.zasp_runtime_gateway_record_event(text,text,bigint,bigint,bytea,bigint,text,text,jsonb,timestamptz) TO zasp_gateway_control;
GRANT EXECUTE ON FUNCTION public.zasp_security_agent_schedule_triggers_v24(text,integer),public.zasp_security_agent_prepare_run_v24(text,text,text,text,text,text,text,timestamptz,text,text),public.zasp_security_agent_execute_run_v24(text,text,text,text,text,text,text,text) TO zasp_security_agent_worker;
GRANT EXECUTE ON FUNCTION public.zasp_security_agent_run_v24(text,text,text,text,text,text,bigint,text,text,text,text,text,text),public.zasp_security_agent_run_detail_v24(text,text,text,text),public.zasp_security_agent_approval_page_v24(text,text,text,text,text,timestamptz,text,integer),public.zasp_security_agent_approval_detail_v24(text,text,text,text),public.zasp_security_agent_decide_approval_v24(text,text,text,text,text,text,bigint,text,timestamptz,text,text,text) TO zasp_security_agent_api;
GRANT EXECUTE ON FUNCTION public.zasp_security_agent_claim_session_policy_effects(text,text,integer,integer),public.zasp_security_agent_heartbeat_session_policy_effect(text,text,text,text,text,text,text,integer),public.zasp_security_agent_store_session_policy_target(text,text,text,text,text,text,text,text,text,text,bigint,bigint,text,timestamptz,timestamptz,text,bytea,jsonb,bytea,bytea),public.zasp_security_agent_read_session_policy_target(text,text,text,text,text,text,text),public.zasp_security_agent_finish_session_policy_effect(text,text,text,text,text,text,text,text,bytea,text,text) TO zasp_security_agent_action_worker;

CREATE FUNCTION public.zasp_security_agent_session_isolation_security_ready() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO pg_catalog, public AS $security$
  SELECT zasp_security_agent_connector_revocation_security_ready()
    AND EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.zasp_security_agent_definitions'::regclass AND conname='zasp_security_agent_session_isolation_supervised_check' AND convalidated)
    AND EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.zasp_security_agent_temporary_policy_targets'::regclass AND conname='zasp_security_agent_temporary_policy_targets_action_key_check' AND convalidated AND pg_get_constraintdef(oid,true) LIKE '%isolate_session%')
    AND EXISTS(SELECT 1 FROM pg_class WHERE oid='public.zasp_runtime_gateway_events_session_v24_idx'::regclass AND relkind='i')
    AND has_function_privilege('zasp_security_agent_worker','public.zasp_security_agent_schedule_triggers_v24(text,integer)','EXECUTE') AND has_function_privilege('zasp_security_agent_worker','public.zasp_security_agent_prepare_run_v24(text,text,text,text,text,text,text,timestamptz,text,text)','EXECUTE') AND has_function_privilege('zasp_security_agent_worker','public.zasp_security_agent_execute_run_v24(text,text,text,text,text,text,text,text)','EXECUTE')
    AND has_function_privilege('zasp_security_agent_action_worker','public.zasp_security_agent_claim_session_policy_effects(text,text,integer,integer)','EXECUTE') AND NOT has_function_privilege('zasp_security_agent_worker','public.zasp_security_agent_claim_session_policy_effects(text,text,integer,integer)','EXECUTE') AND NOT has_function_privilege('zasp_gateway_control','public.zasp_security_agent_claim_session_policy_effects(text,text,integer,integer)','EXECUTE')
    AND has_function_privilege('zasp_security_agent_api','public.zasp_security_agent_run_v24(text,text,text,text,text,text,bigint,text,text,text,text,text,text)','EXECUTE') AND has_function_privilege('zasp_security_agent_api','public.zasp_security_agent_run_detail_v24(text,text,text,text)','EXECUTE') AND has_function_privilege('zasp_security_agent_api','public.zasp_security_agent_decide_approval_v24(text,text,text,text,text,text,bigint,text,timestamptz,text,text,text)','EXECUTE')
    AND has_function_privilege('zasp_gateway_control','public.zasp_runtime_gateway_record_event(text,text,bigint,bigint,bytea,bigint,text,text,jsonb,timestamptz)','EXECUTE') AND NOT has_function_privilege('zasp_security_agent_action_worker','public.zasp_runtime_gateway_record_event(text,text,bigint,bigint,bytea,bigint,text,text,jsonb,timestamptz)','EXECUTE')
    AND to_regprocedure('public.zasp_runtime_gateway_record_event_v23_restore(text,text,bigint,bigint,bytea,bigint,text,text,jsonb,timestamptz)') IS NOT NULL
    AND to_regprocedure('public.zasp_security_agent_execution_control_detail_v23_restore(text,text,text)') IS NOT NULL
    AND to_regprocedure('public.zasp_security_agent_mutate_execution_control_v23_restore(text,text,text,text,text,text,text,boolean,bigint,timestamptz,text,text,text)') IS NOT NULL
$security$;

CREATE FUNCTION public.zasp_security_agent_session_isolation_live_fingerprint() RETURNS text LANGUAGE sql STABLE SET search_path TO pg_catalog, public AS $fingerprint$
  WITH identities(value) AS (
    SELECT concat_ws('|','prior_live',zasp_security_agent_connector_revocation_live_fingerprint())
    UNION ALL SELECT concat_ws('|','table',class.relname,owner.rolname,class.relrowsecurity,class.relforcerowsecurity,COALESCE(class.relacl::text,'')) FROM pg_class class JOIN pg_namespace namespace ON namespace.oid=class.relnamespace JOIN pg_roles owner ON owner.oid=class.relowner WHERE namespace.nspname='public' AND class.relname='zasp_security_agent_temporary_policy_targets' AND class.relkind IN('r','i')
    UNION ALL SELECT concat_ws('|','column',attribute.attname,attribute.atttypid::regtype::text,attribute.attnotnull,attribute.attidentity,attribute.attgenerated,COALESCE(pg_get_expr(default_value.adbin,default_value.adrelid),'')) FROM pg_attribute attribute LEFT JOIN pg_attrdef default_value ON default_value.adrelid=attribute.attrelid AND default_value.adnum=attribute.attnum WHERE attribute.attrelid='public.zasp_security_agent_temporary_policy_targets'::regclass AND attribute.attnum>0 AND NOT attribute.attisdropped
    UNION ALL SELECT concat_ws('|','table_constraint',constraint_value.conname,constraint_value.contype,constraint_value.convalidated,constraint_value.condeferrable,constraint_value.condeferred,pg_get_constraintdef(constraint_value.oid,true)) FROM pg_constraint constraint_value WHERE constraint_value.conrelid='public.zasp_security_agent_temporary_policy_targets'::regclass
    UNION ALL SELECT concat_ws('|','index',index_class.relname,index_value.indisvalid,index_value.indisready,index_value.indisunique,index_value.indisprimary,pg_get_indexdef(index_value.indexrelid)) FROM pg_index index_value JOIN pg_class index_class ON index_class.oid=index_value.indexrelid WHERE (index_value.indrelid='public.zasp_runtime_gateway_events'::regclass AND index_class.relname='zasp_runtime_gateway_events_session_v24_idx') OR index_value.indrelid='public.zasp_security_agent_temporary_policy_targets'::regclass
    UNION ALL SELECT concat_ws('|','function',procedure.proname,pg_get_function_identity_arguments(procedure.oid),owner.rolname,procedure.prosecdef,COALESCE(procedure.proconfig::text,''),COALESCE(procedure.proacl::text,''),pg_get_functiondef(procedure.oid)) FROM pg_proc procedure JOIN pg_namespace namespace ON namespace.oid=procedure.pronamespace JOIN pg_roles owner ON owner.oid=procedure.proowner WHERE namespace.nspname='public' AND procedure.proname=ANY(ARRAY['zasp_runtime_gateway_record_event','zasp_runtime_gateway_record_event_v23_restore','zasp_security_agent_execution_control_detail','zasp_security_agent_execution_control_detail_v23_restore','zasp_security_agent_mutate_execution_control','zasp_security_agent_mutate_execution_control_v23_restore','zasp_security_agent_schedule_session_isolation_triggers','zasp_security_agent_schedule_triggers_v24','zasp_security_agent_run_v24','zasp_security_agent_prepare_session_isolation_run','zasp_security_agent_prepare_run_v24','zasp_security_agent_dispatch_session_isolation_run','zasp_security_agent_execute_run_v24','zasp_security_agent_claim_session_policy_effects','zasp_security_agent_heartbeat_session_policy_effect','zasp_security_agent_store_session_policy_target','zasp_security_agent_read_session_policy_target','zasp_security_agent_finish_session_policy_effect','zasp_security_agent_approval_value_v24','zasp_security_agent_run_detail_v24','zasp_security_agent_approval_page_v24','zasp_security_agent_approval_detail_v24','zasp_security_agent_decide_approval_v24','zasp_security_agent_session_isolation_security_ready','zasp_workflow_mutate','zasp_risk_mutate'])
    UNION ALL SELECT concat_ws('|','constraint',conname,convalidated,pg_get_constraintdef(oid,true)) FROM pg_constraint WHERE conrelid='public.zasp_security_agent_definitions'::regclass AND conname='zasp_security_agent_session_isolation_supervised_check'
  ) SELECT encode(digest(convert_to(string_agg(value,E'\n' ORDER BY value),'UTF8'),'sha256'),'hex') FROM identities
$fingerprint$;

CREATE FUNCTION public.zasp_security_agent_session_isolation_readiness(expected_checksum text,expected_fingerprint text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO pg_catalog, public AS $readiness$
  SELECT length(expected_checksum)=64 AND expected_checksum~'^[a-f0-9]{64}$' AND length(expected_fingerprint)=64 AND expected_fingerprint~'^[a-f0-9]{64}$'
    AND EXISTS(SELECT 1 FROM zasp_schema_versions WHERE version=24 AND name='security_agent_session_isolation' AND checksum=expected_checksum)
    AND EXISTS(SELECT 1 FROM zasp_schema_metadata WHERE key='production_core_schema' AND value='security-agent-session-isolation-v1') AND NOT EXISTS(SELECT 1 FROM zasp_schema_versions WHERE version>24)
    AND zasp_security_agent_session_isolation_security_ready() AND zasp_security_agent_session_isolation_live_fingerprint()=expected_fingerprint
$readiness$;
